"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9403],{51018:e=>{e.exports=JSON.parse('{"functions":[{"name":"flush","desc":"Flushes the `maze` namespace. Runs in `Phases.Last`.\\n\\nLync buffers every fire and every request until a flush, so without this\\nnothing leaves either side. `Phases.Last` is what makes it the tick\'s final\\nword: `replecs` fires in the default `Phases.Update`, and a flush connected\\nto `PostSimulation` by hand would race that on connection order instead.\\n\\nNo budget is passed. The budget throttles replicated sets, and this\\nnamespace has none \u2014 packets and requests always go out whole.","params":[{"name":"_world","desc":"Injected by planck; unused here.","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":28,"path":"src/main/shared/systems/flush.luau"}}],"properties":[],"types":[],"name":"flush","desc":"Hands Lync everything buffered this tick.","tags":["shared-system"],"source":{"line":7,"path":"src/main/shared/systems/flush.luau"}}')}}]);